// Actual stopped-thread instruction observations. No guest result injection.
#pragma once
#include "trace_points.hpp"
struct TraceCell {unsigned address,width,read,write,segment,before_valid,after_valid,before_lo,before_hi,after_lo,after_hi;};
struct TraceEvent {unsigned index,pc,next_pc,exception_eip,opcode,count,thread,kind;CONTEXT before,after;TraceCell cells[4];unsigned char frame_before[64],frame_after[64];};
struct ApiEvent {unsigned index,source_pc,target,return_pc,import_index,argc,returned,thread,error_before,error_after;CONTEXT entry,after;unsigned char frame[64],returned_frame[64];};
static TraceEvent trace_events[32768]{};static ApiEvent trace_apis[512]{};static unsigned trace_count{},trace_api_count{},trace_active{},trace_owner{};
static unsigned char trace_original[trace_points.size()]{};
static unsigned trace_register(const CONTEXT&c,unsigned i){switch(i){case 0:return c.Eax;case 1:return c.Ecx;case 2:return c.Edx;case 3:return c.Ebx;case 4:return c.Esp;case 5:return c.Ebp;case 6:return c.Esi;case 7:return c.Edi;default:return 0;}}
static void trace_begin(){trace_owner=GetCurrentThreadId();trace_count=trace_api_count=0;for(unsigned i=0;i<trace_points.size();++i){auto*p=reinterpret_cast<unsigned char*>(trace_points[i].pc);require(*p==trace_points[i].opcode,"Exact genuine source first byte before trace");trace_original[i]=*p;DWORD old{},ignored{};require(VirtualProtect(p,1,PAGE_EXECUTE_READWRITE,&old),"Trace source writable");*p=0xcc;require(FlushInstructionCache(GetCurrentProcess(),p,1)&&VirtualProtect(p,1,old,&ignored),"Trace source initial breakpoint");}trace_active=1;}
static void trace_finish(){trace_active=0;for(unsigned i=0;i<trace_points.size();++i){auto*p=reinterpret_cast<unsigned char*>(trace_points[i].pc);DWORD old{},ignored{};require(VirtualProtect(p,1,PAGE_EXECUTE_READWRITE,&old),"Trace source restore writable");*p=trace_original[i];require(FlushInstructionCache(GetCurrentProcess(),p,1)&&VirtualProtect(p,1,old,&ignored),"Trace source restored");}}
static void trace_dump(){const std::array<unsigned,6> schema{sizeof(TraceEvent),sizeof(ApiEvent),sizeof(TraceCell),sizeof(CONTEXT),trace_count,trace_api_count};dump("trace/schema.bin",schema.data(),sizeof(schema));dump("trace/events.bin",trace_events,trace_count*sizeof(TraceEvent));dump("trace/APIs.bin",trace_apis,trace_api_count*sizeof(ApiEvent));for(unsigned i=0;i<trace_api_count;++i){const auto&a=trace_apis[i];auto name=std::string(api_imports[a.import_index].name);if(!a.returned||!a.after.Eax)continue;unsigned pointer=a.after.Eax,handle=pointer;if(name!="GlobalAlloc"&&name!="GlobalLock"&&name!="LocalAlloc")continue;if(name=="GlobalLock")std::memcpy(&handle,a.frame+4,4);const auto size=name=="LocalAlloc"?LocalSize(reinterpret_cast<HLOCAL>(handle)):GlobalSize(reinterpret_cast<HGLOBAL>(handle));std::array<unsigned,6>m{i,pointer,handle,static_cast<unsigned>(size),a.source_pc,a.return_pc};dump("trace/allocation-final/"+std::to_string(i)+"-meta.bin",m.data(),sizeof(m));if(size&&size<=65536){std::vector<unsigned char>b(size);if(safe_read(reinterpret_cast<void*>(pointer),b.data(),size))dump("trace/allocation-final/"+std::to_string(i)+"-bytes.bin",b.data(),b.size());}}}
static bool trace_debug(HANDLE child,const DEBUG_EVENT&event){
 auto code=event.u.Exception.ExceptionRecord.ExceptionCode;if(code!=EXCEPTION_BREAKPOINT&&code!=EXCEPTION_SINGLE_STEP&&code!=0x4000001fU)return false;
 auto get=[&](const void*a,void*b,SIZE_T n){SIZE_T got{};require(ReadProcessMemory(child,a,b,n,&got)&&got==n,"Stopped actual child read");};auto put=[&](void*a,const void*b,SIZE_T n){SIZE_T got{};require(WriteProcessMemory(child,a,b,n,&got)&&got==n,"Trace record write");};
 unsigned active{},owner{},teb{};get(&trace_active,&active,4);if(!active)return false;get(&trace_owner,&owner,4);get(&probe_teb,&teb,4);require(owner==event.dwThreadId,"Exact source trace thread");mw34::original_broker::Handle thread(OpenThread(THREAD_GET_CONTEXT|THREAD_SET_CONTEXT|THREAD_QUERY_INFORMATION,FALSE,owner));require(thread.value!=nullptr,"Stopped thread handle");CONTEXT c{};c.ContextFlags=CONTEXT_FULL|CONTEXT_FLOATING_POINT|CONTEXT_EXTENDED_REGISTERS;require(GetThreadContext(thread.value,&c),"Whole actual x86 CONTEXT");
 static unsigned pending=~0U;static TraceEvent measured{};static std::vector<ApiEvent> APIs;
 auto patch=[&](unsigned pc,unsigned char b){DWORD old{},ignored{};auto*p=reinterpret_cast<void*>(pc);require(VirtualProtectEx(child,p,1,PAGE_EXECUTE_READWRITE,&old),"Stopped source writable");put(p,&b,1);require(FlushInstructionCache(child,p,1)&&VirtualProtectEx(child,p,1,old,&ignored),"Stopped source permission/cache restore");};
 auto maybe=[&](unsigned address,void*p,unsigned n){SIZE_T got{};return ReadProcessMemory(child,reinterpret_cast<void*>(address),p,n,&got)&&got==n;};
 auto cell=[&](TraceCell&v,bool after){unsigned words[2]{};bool ok=maybe(v.address,words,v.width);if(after){v.after_valid=ok;v.after_lo=words[0];v.after_hi=words[1];}else{v.before_valid=ok;v.before_lo=words[0];v.before_hi=words[1];}};
 auto publish_API=[&](const ApiEvent&a){put(&trace_apis[a.index],&a,sizeof(a));unsigned n=a.index+1;put(&trace_api_count,&n,4);};
 if(code==EXCEPTION_SINGLE_STEP){require(pending<trace_points.size(),"One pending physical source step");measured.after=c;measured.next_pc=c.Eip;maybe(c.Esp,measured.frame_after,64);for(unsigned i=0;i<measured.count;++i)cell(measured.cells[i],true);patch(trace_points[pending].pc,0xcc);put(&trace_events[measured.index],&measured,sizeof(measured));unsigned n=measured.index+1;put(&trace_count,&n,4);
  unsigned targets[api_imports.size()]{};get(api_targets,targets,sizeof(targets));unsigned ai=~0U;for(unsigned i=0;i<api_imports.size();++i)if(targets[i]==c.Eip){if(ai==~0U||api_imports[i].iat>=0x5f400000)ai=i;}
  if(ai!=~0U){require(APIs.size()<512,"Bounded actual API intervals");ApiEvent a{};a.index=APIs.size();a.source_pc=measured.pc;a.target=c.Eip;a.import_index=ai;a.argc=api_imports[ai].argc;a.thread=owner;a.entry=c;require(maybe(c.Esp,a.frame,64),"Whole actual entered API frame");std::memcpy(&a.return_pc,a.frame,4);maybe(teb+0x34,&a.error_before,4);APIs.push_back(a);publish_API(a);}
  pending=~0U;c.EFlags&=~0x100U;require(SetThreadContext(thread.value,&c),"Continue actual source removing observer TF");return true;
 }
 const auto pc=reinterpret_cast<unsigned>(event.u.Exception.ExceptionRecord.ExceptionAddress);unsigned point=~0U;for(unsigned i=0;i<trace_points.size();++i)if(trace_points[i].pc==pc){point=i;break;}if(point==~0U)return false;require(pending==~0U&&c.Eip==pc+1,"Exact breakpoint source provenance");
 for(auto it=APIs.rbegin();it!=APIs.rend();++it)if(!it->returned&&it->return_pc==pc){auto&a=*it;a.returned=1;a.after=c;a.after.Eip=pc;require(maybe(c.Esp,a.returned_frame,64),"Whole actual returned source frame");maybe(teb+0x34,&a.error_after,4);publish_API(a);auto name=std::string(api_imports[a.import_index].name);if(c.Eax&&(name=="GlobalAlloc"||name=="GlobalLock"||name=="LocalAlloc"||name=="GlobalReAlloc"||name=="LocalReAlloc")){const auto base=c.Eax&~4095U;std::vector<unsigned>pages;for(unsigned off=0;off<65536;off+=4096){std::array<unsigned char,4096>v{};if(!maybe(base+off,v.data(),4096))break;pages.push_back(base+off);dump("trace/allocation-initial/"+std::to_string(a.index)+"/"+std::to_string(base+off)+".bin",v.data(),v.size());}dump("trace/allocation-initial/"+std::to_string(a.index)+"/pages.bin",pages.data(),pages.size()*4);}break;}
 unsigned n{};get(&trace_count,&n,4);require(n<32768,"Bounded actual instructions");measured={};measured.index=n;measured.pc=pc;measured.exception_eip=c.Eip;measured.opcode=trace_points[point].opcode;measured.before=c;measured.thread=owner;measured.count=trace_points[point].count;require(maybe(c.Esp,measured.frame_before,64),"Whole actual source stack window");
 const auto&p=trace_points[point];for(unsigned i=0;i<p.count;++i){const auto&m=p.cells[i];auto&v=measured.cells[i];v.address=m.displacement;for(unsigned r=0;r<8;++r)v.address+=trace_register(c,r)*m.coefficients[r];if(m.segment)v.address+=teb;v.segment=m.segment;v.width=m.width;v.read=m.read;v.write=m.write;cell(v,false);}
 patch(pc,static_cast<unsigned char>(p.opcode));c.Eip=pc;c.EFlags|=0x100U;pending=point;require(SetThreadContext(thread.value,&c),"Execute genuine physical instruction");return true;
}
